const {app,BrowserWindow,session}=require('electron'),fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict')
const root=path.resolve(__dirname,'../..'),dir=path.join(root,'qa-artifacts/design-bindings')
fs.mkdirSync(dir,{recursive:true});app.setPath('userData',fs.mkdtempSync(path.join(dir,'profile-')));app.disableHardwareAcceleration()
async function main(){
 await app.whenReady();session.defaultSession.webRequest.onBeforeRequest((r,cb)=>cb({cancel:/^https?:/.test(r.url)}))
 const result=await require('esbuild').build({stdin:{contents:`import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {DesignControls,DEFAULT_DESIGN} from './src/DesignControls';function Demo(){const [value,setValue]=useState({...DEFAULT_DESIGN,quality:'high',count:4,bindings:{}});window.value=value;window.reset=()=>setValue(v=>({...v,bindings:{}}));return <DesignControls value={value} onChange={setValue} mode="generate" onModeChange={()=>{}} references={[]} onReference={()=>{}}/>}createRoot(document.getElementById('root')).render(<Demo/>);`,resolveDir:root,loader:'tsx'},bundle:true,write:false,format:'iife',define:{'process.env.NODE_ENV':'"production"'}})
 const file=path.join(dir,'fixture.html');fs.writeFileSync(file,`<meta charset="utf-8"><style>body{font:14px 'Segoe UI','Microsoft YaHei';padding:30px}summary,button{padding:8px;cursor:pointer}details{display:inline-block;vertical-align:top;margin:5px}.composer-popover{position:absolute;top:100px;background:#fff;border:1px solid #ddd;max-width:340px;padding:12px;z-index:1}button{display:block}.design-controls details[data-bound=true]>summary{background:#e9f3fb;color:#2785bb}</style><div id="root"></div><script>${result.outputFiles[0].text}</script>`)
 const win=new BrowserWindow({show:false,width:1400,height:900,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,offscreen:true}})
 await win.loadFile(file);const run=s=>win.webContents.executeJavaScript(s,true),wait=()=>new Promise(r=>setTimeout(r,90));await wait()
 assert.deepEqual(await run('window.value.bindings'),{})
 assert.ok(await run(`document.body.innerText.includes('尺寸 自动')&&document.body.innerText.includes('数量 自动')`))
 const click=async text=>{await run(`(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.textContent===${JSON.stringify(text)});if(!b)throw Error('missing button');b.closest('details').open=true;b.click()})()`);await wait()}
 await click('高');assert.deepEqual(await run('window.value.bindings'),{quality:true})
 await click('2 张');assert.deepEqual(await run('window.value.bindings'),{quality:true,count:true})
 await run(`document.querySelector('[aria-label="图片尺寸"]').parentElement.open=true;document.querySelector('.design-business-options button').click()`);await wait()
 assert.equal(await run('window.value.bindings.size'),true)
 await click('不绑定质量，按提示词或自动');assert.equal(await run('window.value.bindings.quality'),false);assert.equal(await run('window.value.bindings.count'),true)
 await run(`window.sent=structuredClone(window.value);window.reset()`);await wait()
 assert.deepEqual(await run('window.value.bindings'),{});assert.equal(await run('window.sent.bindings.count'),true)
 await run(`document.querySelectorAll('details').forEach(d=>d.open=false)`)
 fs.writeFileSync(path.join(dir,'unbound.png'),(await win.webContents.capturePage()).toPNG())
 console.log('DESIGN_BINDINGS_UI_PASS: default unbound, independent selection, unbind, immutable sent snapshot');win.destroy();app.quit()
}
main().catch(e=>{console.error(e);app.exit(1)})
